query.base:
TS metrics-gcp.compute.otel-*
// Compute Engine VM instances only
| WHERE resource.attributes.gcp.resource_type == "gce_instance"
    // Only docs carrying the firewall metric (keeps per-bucket state small)
    AND `compute.googleapis.com/firewall/dropped_packets_count` IS NOT NULL
// dropped_packets_count is a DELTA metric stored as a gauge (packets per 60s sample). Never use RATE().
// OTel TSDS splits one entity's metric into several series (_metric_names_hash is a dimension),
// so per-entity means are SUM(SUM_OVER_TIME) / SUM(COUNT_OVER_TIME), never SUM/MAX of AVG_OVER_TIME.
// Per-VM dropped packets/s per 5-minute bucket, then summed to the zone.
| STATS
    drop_sum = SUM(SUM_OVER_TIME(`compute.googleapis.com/firewall/dropped_packets_count`)),
    drop_n = SUM(COUNT_OVER_TIME(`compute.googleapis.com/firewall/dropped_packets_count`))
  BY time_bucket = TBUCKET(5 minutes), resource.attributes.project_id, resource.attributes.zone, resource.attributes.instance_id
| WHERE drop_n > 0
| EVAL vm_dropped_pps = TO_DOUBLE(drop_sum) / drop_n / 60.0
| STATS dropped_pps = SUM(vm_dropped_pps)
  BY time_bucket, resource.attributes.project_id, resource.attributes.zone
// Compare the recent buckets with the typical (median) bucket in the lookback window.
// Recent = buckets that started in the last 15 minutes. Cloud Monitoring data arrives 5-8 minutes late,
// so this always includes a populated bucket, and the alert recovers 15-20 minutes after a spike ends
// (comparing the window peak instead would keep it active until the spike leaves the 60-minute lookback).
| STATS
    recent_dropped_pps = MAX(dropped_pps) WHERE time_bucket >= NOW() - 15 minutes,
    peak_dropped_pps = MAX(dropped_pps),
    baseline_dropped_pps = MEDIAN(dropped_pps),
    buckets = COUNT(*)
  BY resource.attributes.project_id, resource.attributes.zone
// Floor of 1 packet/s avoids division by zero when the baseline is silent.
| EVAL spike_ratio = ROUND(recent_dropped_pps / GREATEST(baseline_dropped_pps, 1.0), 1)
| EVAL recent_dropped_pps = ROUND(recent_dropped_pps, 1), peak_dropped_pps = ROUND(peak_dropped_pps, 1), baseline_dropped_pps = ROUND(baseline_dropped_pps, 1)
